WITH metrics AS (SELECT *, LEAD(quantity, 2, 0) OVER (PARTITION BY store_id ORDER BY quantity, id) AS next_quantity, STDDEV_SAMP(quantity) OVER w_recent AS store_id_stddev_samp_quantity FROM inventory WINDOW w_recent AS (PARTITION BY store_id)) SELECT CASE WHEN quantity >= 180 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, APPROX_PERCENTILE(next_quantity, 0.95) AS next_quantity_p95, BIT_AND(quantity) AS quantity_bit_and, PERCENTILE_APPROX(store_id_stddev_samp_quantity, ARRAY(0.25, 0.5, 0.75)) AS store_id_stddev_samp_quantity_quartiles, COUNT(DISTINCT store_id) AS distinct_store_ids, MAX(store_id_stddev_samp_quantity) AS max_store_id_stddev_samp_quantity FROM metrics GROUP BY CASE WHEN quantity >= 180 THEN 'LARGE' ELSE 'SMALL' END HAVING next_quantity_p95 > 0 ORDER BY next_quantity_p95;
